import { SVGIcon } from '@progress/kendo-react-common';
import * as React from 'react';
/**
 * Defines the props for the `Thought` component.
 *
 * `Thought` is a non-expandable sub-step item rendered inside a `ChainOfThought`.
 * It displays an icon, label, optional metadata (diff counts, timestamp, status),
 * and an optional completed indicator.
 *
 * Extends `React.HTMLAttributes<HTMLDivElement>` to allow passing standard HTML
 * attributes (e.g. `className`, `style`, `id`) directly to the root element.
 *
 * @hidden
 */
export interface ThoughtProps extends React.HTMLAttributes<HTMLDivElement> {
    /**
     * The SVG icon displayed at the start of the thought row.
     * Pass an icon object from `@progress/kendo-svg-icons`.
     */
    svgIcon?: SVGIcon;
    /**
     * The primary label text displayed in the thought row.
     */
    label?: string;
    /**
     * Additional CSS class name(s) applied to the label element.
     * Use to override or augment the default label styling.
     */
    labelClassName?: string;
    /**
     * An optional secondary label displayed alongside the primary label,
     * typically used for a brief contextual note or sub-title.
     * Duration information should be included here when needed.
     */
    secondaryLabel?: string;
    /**
     * The number of lines added in this thought, shown as a green diff indicator.
     */
    linesAdded?: number;
    /**
     * The number of lines removed in this thought, shown as a red diff indicator.
     */
    linesRemoved?: number;
    /**
     * A text label for the status badge rendered in the thought row.
     */
    status?: string;
    /**
     * The theme color applied to the status badge.
     * Maps to the Kendo theme color palette.
     *
     * - `'base'` — neutral/default
     * - `'success'` — green, used for completed states
     * - `'warning'` — yellow/orange, used for pending states
     * - `'error'` — red, used for failure states
     * - `'info'` — blue, used for informational states
     */
    statusThemeColor?: 'base' | 'success' | 'warning' | 'error' | 'info';
    /**
     * An SVG icon displayed alongside the status badge.
     * Pass an icon object from `@progress/kendo-svg-icons`.
     */
    statusSvgIcon?: SVGIcon;
    /**
     * When `true`, the thought row is marked as completed.
     * Completed thoughts render with a distinct visual treatment (no shimmer).
     * When `false` or omitted, the thought renders as active (with shimmer animation).
     */
    completed?: boolean;
    /**
     * An optional description text rendered below the primary label.
     * Use for additional context about what the thought represents.
     */
    description?: string;
    /**
     * @hidden
     * Replaces the inner content of `k-agent-step-content` when provided.
     * Used by `ChainOfThought` to slot a custom `thoughtTemplate` output.
     */
    contentNode?: React.ReactNode;
}
